function login() {
  var u = '';
  var p = '';
  try { u = String(result['用户名'] || ''); } catch (e1) {}
  try { p = String(result['密码'] || ''); } catch (e2) {}
  u = u.replace(/^\s+|\s+$/g, '');
  p = p.replace(/^\s+|\s+$/g, '');
  if (!u) { try { java.longToast('请填写用户名'); } catch (e) {} return; }
  if (!p) { try { java.longToast('请填写密码'); } catch (e) {} return; }
  var resp = null;
  var txt = '';
  try {
    resp = java.post('https://wap.39shuwu.com/api/login',
      'username=' + encodeURIComponent(u) + '&password=' + encodeURIComponent(p),
      {
        'User-Agent': 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36',
        'Referer': 'https://wap.39shuwu.com/user/login.html',
        'Origin': 'https://wap.39shuwu.com',
        'X-Requested-With': 'XMLHttpRequest',
        'Content-Type': 'application/x-www-form-urlencoded'
      });
    txt = String(resp.body());
  } catch (e3) {
    try { java.longToast('登录请求失败: ' + e3); } catch (e) {}
    return;
  }
  var ok = false;
  var msg = '';
  try {
    var jo = JSON.parse(txt);
    ok = (String(jo.code) === '0');
    msg = String(jo.msg || '');
  } catch (e4) {
    ok = (txt.indexOf('\"code\":0') >= 0);
    msg = ok ? '' : txt.substring(0, 120);
  }
  if (ok) {
    var saved = false;
    try {
      if (resp !== null) {
        var sc = resp.header('Set-Cookie');
        if (sc) {
          var sid = '';
          var arr = String(sc).split(/,\s*(?=[A-Za-z0-9_]+=)/);
          for (var i = 0; i < arr.length; i++) {
            var one = arr[i];
            var mm = one.match(/(^|;\s*)SID=([^;]+)/);
            if (mm) { sid = mm[2]; break; }
          }
          if (sid) {
            cookie.setCookie('https://wap.39shuwu.com/', 'SID=' + sid);
            saved = true;
          }
        }
      }
    } catch (e5) {}
    try { java.put('fqLoginMsg', '登录成功'); } catch (e) {}
    try { java.upLoginData({ '登录状态': '✅ 登录成功' + (saved ? '' : '(cookie待确认)') }); } catch (e) {}
    try { java.longToast('✅ 登录成功'); } catch (e) {}
    try { java.toast('登录成功'); } catch (e) {}
    try { java.reLoginView(false); } catch (e) {}
  } else {
    var em = msg ? msg : '登录失败';
    try { java.put('fqLoginMsg', em); } catch (e) {}
    try { java.upLoginData({ '登录状态': '❌ ' + em }); } catch (e) {}
    try { java.longToast('❌ ' + em); } catch (e) {}
    try { java.toast(em); } catch (e) {}
  }
}
